<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
$sales=$conn->query("SELECT s.id,s.invoice_number,s.sale_date,s.total_amount,COALESCE(c.customer_name,'Walk-in Customer') customer_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN deliveries d ON d.sale_id=s.id WHERE s.sale_status='Completed' AND d.id IS NULL ORDER BY s.id DESC")->fetchAll();
$drivers=$conn->query("SELECT id,full_name FROM users WHERE status='Active' AND role='Driver' ORDER BY full_name")->fetchAll();
$list=$conn->query("SELECT d.*,s.invoice_number,COALESCE(c.customer_name,'Walk-in Customer') customer_name,u.full_name driver_name FROM deliveries d JOIN sales s ON s.id=d.sale_id LEFT JOIN customers c ON c.id=d.customer_id LEFT JOIN users u ON u.id=d.driver_id ORDER BY d.id DESC LIMIT 50")->fetchAll();
$flash=$_SESSION['delivery_flash']??null;unset($_SESSION['delivery_flash']);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?><main class="content"><style>.grid{display:grid;grid-template-columns:380px 1fr;gap:18px}.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 4px #0001}.field{margin:11px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:5px}.field input,.field select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #dbe3ec;border-radius:7px}.btn{border:0;background:#004a99;color:#fff;border-radius:7px;padding:11px 15px;font-weight:700;cursor:pointer;width:100%}.flash{padding:12px;background:#ecfdf5;color:#166534;border-radius:8px;margin-bottom:12px}.table{width:100%;border-collapse:collapse}.table th{background:#004a99;color:#fff;padding:10px;text-align:left}.table td{padding:10px;border-bottom:1px solid #e5e7eb;font-size:13px}.status{font-weight:700}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style><h1>Deliveries</h1><p>Dispatch completed sales and track delivery status.</p><?php if($flash):?><div class="flash"><?=e($flash)?></div><?php endif;?><div class="grid"><div class="panel"><h3>Create Delivery</h3><form method="post" action="store.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label>Sale / Invoice</label><select name="sale_id" required><option value="">Select sale</option><?php foreach($sales as $s):?><option value="<?=$s['id']?>"><?=e($s['invoice_number'])?> — <?=e($s['customer_name'])?> — KES <?=number_format((float)$s['total_amount'],2)?></option><?php endforeach;?></select></div><div class="field"><label>Driver</label><select name="driver_id"><option value="">Unassigned</option><?php foreach($drivers as $d):?><option value="<?=$d['id']?>"><?=e($d['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Delivery Address</label><input name="delivery_address" required maxlength="300"></div><div class="field"><label>Delivery Date</label><input type="date" name="delivery_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Notes</label><input name="notes" maxlength="500"></div><button class="btn">Create Delivery</button></form></div><div class="panel"><h3>Delivery Register</h3><div style="overflow:auto"><table class="table"><thead><tr><th>Delivery</th><th>Invoice</th><th>Customer</th><th>Driver</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($list as $d):?><tr><td><?=e($d['delivery_number'])?></td><td><?=e($d['invoice_number'])?></td><td><?=e($d['customer_name'])?></td><td><?=e($d['driver_name']??'Unassigned')?></td><td><?=e($d['delivery_date'])?></td><td class="status"><?=e($d['status'])?></td><td><form method="post" action="status.php" style="display:flex;gap:5px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$d['id']?>"><select name="status"><option>Pending</option><option>Dispatched</option><option>Out for Delivery</option><option>Delivered</option><option>Failed</option><option>Cancelled</option></select><button class="btn" style="width:auto;padding:7px 10px">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></main><?php require_once __DIR__.'/../../includes/footer.php';?>